const id="00000000-0000-4000-8000-0000e0000001";
let all=[],cur;
do{const r=await tools["API-query-data-source"]({data_source_id:id,start_cursor:cur,page_size:100});all.push(...r.results);cur=r.has_more?r.next_cursor:undefined}while(cur);
const names=new Set(all.flatMap(t=>t.properties.Responsable.people.map(p=>p.name+"|"+p.id)));
console.log([...names]);
const m=all.filter(t=>t.properties.Responsable.people.some(p=>p.name==="Ana Ruiz")&&t.properties.Estado.status.name!=="Hecha"&&["Media","Alta"].includes(t.properties.Prioridad.select?.name));
console.log(m.length, m.map(t=>t.properties.Nombre.title[0].plain_text));

const id="00000000-0000-4000-8000-0000e0000001";
const ds = await tools["API-retrieve-a-data-source"]({data_source_id:id});
console.log(JSON.stringify(ds.properties));
let all=[],c;
do{const r=await tools["API-query-data-source"]({data_source_id:id,start_cursor:c,page_size:100});all.push(...r.results);c=r.has_more?r.next_cursor:undefined}while(c);
console.log(all.length);
console.log(JSON.stringify(all.map(p=>Object.fromEntries(Object.entries(p.properties).map(([k,v])=>[k,v[v.type]&&(v[v.type].name||v[v.type].map?.(z=>z.name||z.id||z.plain_text)||JSON.stringify(v[v.type]))])))));

